{"path":"services.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Sessions & Planning — {{BUSINESS_NAME}}</title>
  <style>
    :root{--accent:#6b8e23;--muted:#6c757d;--bg:#fffaf6;--card:#ffffff;--text:#222}
    html,body{height:100%}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;line-height:1.45;color:var(--text);background:var(--bg) url('assets/img/pattern.svg');-webkit-font-smoothing:antialiased}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;background:linear-gradient(90deg,rgba(107,142,35,0.06),rgba(255,255,255,0));box-shadow:inset 0 -1px 0 rgba(0,0,0,0.03)}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:44px;height:44px;border-radius:10px;background:var(--accent);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700}
    nav a{margin-left:14px;color:var(--muted);text-decoration:none;font-size:14px}
    .cta-btn{background:var(--accent);color:#fff;padding:10px 14px;border-radius:8px;text-decoration:none;font-weight:600}

    main{padding:28px;max-width:1100px;margin:18px auto}
    .hero{display:grid;grid-template-columns:1fr 360px;gap:24px;align-items:start}
    .hero-card{padding:22px;background:var(--card);border-radius:14px;box-shadow:0 6px 18px rgba(17,24,39,0.06)}
    h1{margin:0 0 8px;font-size:26px}
    p.lead{margin:0;color:var(--muted)}

    .section{margin-top:20px}
    .grid-2{display:grid;grid-template-columns:1fr 1fr;gap:18px}
    .pill{display:inline-block;padding:6px 10px;border-radius:999px;background:#f4f7ec;color:var(--accent);font-weight:600;font-size:13px}

    /* Session Planner widget */
    .planner{padding:18px;border-radius:12px;background:linear-gradient(180deg,#fff,#fbfff6);border:1px solid rgba(107,142,35,0.06)}
    label{display:block;margin-top:12px;font-size:13px;color:var(--muted)}
    select,input[type='range'],input[type='number']{width:100%;padding:8px;border-radius:8px;border:1px solid #e6e8ea;margin-top:6px}
    .options{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px}
    .opt{padding:8px 10px;border-radius:8px;background:#fff;border:1px solid #eee;cursor:pointer}
    .opt.active{border-color:var(--accent);box-shadow:0 6px 14px rgba(107,142,35,0.08)}
    .plan-output{white-space:pre-wrap;background:#fcfcfc;padding:12px;border-radius:8px;border:1px dashed #e9ecef;margin-top:12px}
    .row{display:flex;gap:12px}
    .btn{display:inline-block;padding:10px 12px;border-radius:8px;border:0;background:var(--accent);color:#fff;font-weight:600;cursor:pointer}
    .btn.secondary{background:#fff;border:1px solid #ddd;color:var(--accent)}

    /* offers */
    .offer{padding:16px;border-radius:12px;background:#fff;border:1px solid #f0f0f0}
    .price{font-size:20px;font-weight:700;color:var(--accent)}

    footer{margin-top:40px;padding:18px;color:var(--muted);font-size:13px}
    .faq{margin-top:12px;padding:14px;background:#fff;border-radius:10px}
    .faq p{margin:8px 0}
    @media(max-width:880px){.hero{grid-template-columns:1fr}.grid-2{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div class='brand'>
      <div class='logo'>A</div>
      <div>
        <div style='font-weight:700'>{{BUSINESS_NAME}}</div>
        <div style='font-size:12px;color:var(--muted)'>Aromatherapy for everyday rhythms</div>
      </div>
    </div>
    <nav aria-label='Main'>
      <a href='index.html'>Home</a>
      <a href='services.html' style='color:var(--accent);font-weight:600'>Sessions</a>
      <a href='blends.html'>Custom Blends</a>
      <a href='shop.html'>Shop</a>
      <a href='pricing.html'>Plans</a>
      <a class='cta-btn' href='book.html'>{{PRIMARY_CTA_LABEL}}</a>
    </nav>
  </header>

  <main>
    <section class='hero'>
      <div class='hero-card'>
        <span class='pill'>Sessions & Planning</span>
        <h1>Personal scent sessions that fit your routine</h1>
        <p class='lead'>Short consultations, ongoing series, and a planner tool to shape a realistic scent rhythm. No promises of cure — only careful formulations that may support how you feel.</p>

        <div class='section'>
          <h3 style='margin:0 0 8px'>Offerings</h3>
          <div class='grid-2'>
            <div class='offer'>
              <div style='font-size:14px;color:var(--muted)'>Single Session</div>
              <div class='price'>$85</div>
              <p style='margin-top:8px;color:var(--muted)'>A focused 45-minute consultation to discover scent preferences and micro-routines you can try at home.</p>
            </div>
            <div class='offer'>
              <div style='font-size:14px;color:var(--muted)'>Series — Three Visits</div>
              <div class='price'>$230</div>
              <p style='margin-top:8px;color:var(--muted)'>Three sessions designed to introduce, test, and refine small scent practices across weeks.</p>
            </div>
          </div>
        </div>

        <div class='section'>
          <h3 style='margin:0 0 8px'>How we talk about change</h3>
          <p style='margin:0;color:var(--muted)'>We map current habits, pick sensory anchors, and try simple rituals. Plans are practical, tiny, and adjustable.</p>
        </div>

        <div class='section'>
          <button class='btn' onclick="location.href='book.html'">Reserve a Session</button>
          <button class='btn secondary' onclick="document.getElementById('planner').scrollIntoView({behavior:'smooth'})">Try the Planner</button>
        </div>
      </div>

      <aside class='planner hero-card' id='planner' aria-labelledby='planner-title'>
        <h3 id='planner-title' style='margin:0 0 6px'>Session Planner</h3>
        <div style='font-size:13px;color:var(--muted)'>Build a short plan you can take into a consultation or try on your own.</div>

        <label for='goal'>Primary aim</label>
        <select id='goal'>
          <option value='calm'>Calm / De-stress</option>
          <option value='focus'>Focus / Clarity</option>
          <option value='uplift'>Uplift / Energy</option>
          <option value='sleep'>Wind-down / Sleep</option>
          <option value='ground'>Grounding / Balance</option>
        </select>

        <label>Preferred format</label>
        <div class='options' id='formats'>
          <div class='opt active' data-val='diffuser'>Diffuser ritual</div>
          <div class='opt' data-val='roller'>Roller bottle</div>
          <div class='opt' data-val='spritz'>Room spritz</div>
          <div class='opt' data-val='inhaler'>Personal inhaler</div>
        </div>

        <label for='duration'>Session length (minutes)</label>
        <input id='duration' type='number' min='15' max='90' value='45'>

        <label for='freq'>Suggested practice frequency (per week)</label>
        <input id='freq' type='range' min='1' max='7' value='3'>
        <div style='font-size:13px;color:var(--muted);margin-top:6px'>Frequency: <span id='freqVal'>3</span> times/week</div>

        <label for='notes'>Sensory notes you prefer (comma separated)</label>
        <input id='notes' placeholder='e.g., citrus, woody, floral'>

        <div style='margin-top:12px' class='row'>
          <button class='btn' id='buildPlan'>Build plan</button>
          <button class='btn secondary' id='resetPlan'>Clear</button>
        </div>

        <div class='plan-output' id='planOutput' aria-live='polite'>Your plan will appear here.</div>
        <div style='margin-top:8px;display:flex;gap:8px'>
          <button class='btn' id='copyPlan'>Copy text</button>
          <a href='book.html' class='btn secondary'>Bring to booking</a>
        </div>
      </aside>
    </section>

    <section class='section'>
      <div class='hero-card'>
        <h3 style='margin:0 0 8px'>Session formats explained</h3>
        <div style='color:var(--muted)'>
          <strong>Diffuser ritual:</strong> short timed diffusions to anchor mood.
          <br><strong>Roller bottle:</strong> portable blends for targeted touch points.
          <br><strong>Room spritz:</strong> quick resets for shared spaces.
          <br><strong>Personal inhaler:</strong> discreet, on-the-go inhalation support.
        </div>
      </div>
    </section>

    <section class='section'>
      <div class='grid-2'>
        <div class='hero-card'>
          <h4 style='margin:0 0 8px'>Testimonials</h4>
          <p style='margin:0;color:var(--muted)'>"Small, doable scent habits that actually fit my days. The series helped me find a rhythm." — C.</p>
        </div>
        <div class='hero-card'>
          <h4 style='margin:0 0 8px'>Practical notes</h4>
          <p style='margin:0;color:var(--muted)'>Sessions emphasize safety. We include dilution guidance, patch testing, and household considerations, especially around pets and pregnancy.</p>
        </div>
      </div>
    </section>

    <section class='section faq'>
      <h4 style='margin:0 0 8px'>FAQ — Safety & preparation</h4>
      <p><strong>Dilution:</strong> Topical blends typically use low dilutions. Common safe adult ranges are 1–3% for general use; lower rates (0.25–1%) are advised for pregnant people and young children. We include clear drop-based recipes in every plan.</p>
      <p><strong>Patch test:</strong> Always patch test a new blend on a small area of skin for 24 hours. Discontinue if irritation occurs.</p>
      <p><strong>Pets:</strong> Some oils can be harmful to pets. We will flag pet-sensitive scenarios and suggest room-only or pet-safe options.</p>
      <p><strong>Not medical:</strong> Our work is supportive and non-medical. We do not diagnose, treat, or claim cures. Scent work may support wellbeing for some people.</p>
    </section>

  </main>

  <footer>
    <div>Contact us: <a href='tel:{{PHONE}}'>{{PHONE}}</a> • <a href='mailto:{{EMAIL}}'>{{EMAIL}}</a></div>
    <div style='margin-top:6px'>Serving {{CITY}}, {{STATE}} • <a href='privacy.html'>Privacy</a></div>
  </footer>

  <script>
    // Planner logic
    (function(){
      const formats = document.querySelectorAll('#formats .opt');
      formats.forEach(el=>el.addEventListener('click',()=>{formats.forEach(f=>f.classList.remove('active'));el.classList.add('active')}));
      const freq = document.getElementById('freq');
      const freqVal = document.getElementById('freqVal');
      freq.addEventListener('input',()=>freqVal.textContent=freq.value);

      function getActiveFormat(){return document.querySelector('#formats .opt.active').dataset.val}

      document.getElementById('buildPlan').addEventListener('click',()=>{
        const goal = document.getElementById('goal').value;
        const format = getActiveFormat();
        const duration = document.getElementById('duration').value;
        const frequency = document.getElementById('freq').value;
        const notes = document.getElementById('notes').value;

        const plan = [];
        plan.push('Plan:');
        plan.push('- Aim: ' + goal.replace(/\b\w/g, c=>c.toUpperCase()));
        plan.push('- Format: ' + format);
        plan.push('- Session length: ' + duration + ' minutes');
        plan.push('- Suggested frequency: ' + frequency + 'x per week');
        plan.push('- Sensory notes: ' + (notes || 'neutral / unscented preferences'));
        plan.push('\nPractical steps:');
        plan.push('1) Try one short practice for 1 week (' + frequency + ' brief uses).');
        plan.push('2) Keep a quick note of when you used it and what you noticed.');
        plan.push('3) At next check-in, adjust intensity or swap notes.');
        plan.push('\nSafety reminders:');
        plan.push('- Use low dilutions for skin. We recommend following dilution guidance in consultations.');
        plan.push('- Patch test any topical blend; stop use on irritation.');
        plan.push('- Consider pets and pregnancy; ask for pet-safe or pregnancy-aware options.');

        const out = plan.join('\n');
        document.getElementById('planOutput').textContent = out;
      });

      document.getElementById('copyPlan').addEventListener('click',()=>{
        const text = document.getElementById('planOutput').textContent;
        navigator.clipboard && navigator.clipboard.writeText(text).then(()=>{
          const btn = document.getElementById('copyPlan');
          const old = btn.textContent;
          btn.textContent = 'Copied!';
          setTimeout(()=>btn.textContent = old,1500);
        }).catch(()=>alert('Could not copy.'));
      });

      document.getElementById('resetPlan').addEventListener('click',()=>{
        document.getElementById('goal').selectedIndex = 0;
        formats.forEach(f=>f.classList.remove('active'));
        formats[0].classList.add('active');
        document.getElementById('duration').value = 45;
        document.getElementById('freq').value = 3; document.getElementById('freqVal').textContent = 3;
        document.getElementById('notes').value = '';
        document.getElementById('planOutput').textContent = 'Your plan will appear here.';
      });
    })();
  </script>
</body>
</html>"} 
