<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Custom Blends — {{BUSINESS_NAME}}</title>
  <style>
    :root{--accent:#8b5e3c;--muted:#6a6a6a;--bg:#fffdf9;--card:#fff;--text:#222}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;background:var(--bg) url('assets/img/pattern.svg');color:var(--text)}
    header{display:flex;justify-content:space-between;align-items:center;padding:16px 24px;background:rgba(139,94,60,0.04)}
    .nav a{margin-left:12px;color:var(--muted);text-decoration:none}
    .main{max-width:1100px;margin:20px auto;padding:20px}
    .lead{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 6px 20px rgba(0,0,0,0.04)}
    h1{margin:0 0 8px}
    .builder{display:grid;grid-template-columns:360px 1fr;gap:18px;margin-top:18px}
    .card{padding:16px;background:var(--card);border-radius:12px}
    label{font-size:13px;color:var(--muted);display:block;margin-top:10px}
    select,input[type='range'],input[type='number']{width:100%;padding:8px;border-radius:8px;border:1px solid #eee;margin-top:6px}
    .vibes{display:flex;flex-direction:column;gap:8px;margin-top:8px}
    .vibe-btn{padding:8px;border-radius:10px;border:1px solid #f0e9e3;background:#fff;cursor:pointer}
    .vibe-btn.active{border-color:var(--accent);background:linear-gradient(180deg,#fffaf2,#fff)}
    .blend-card{margin-top:12px;padding:12px;border-radius:10px;background:#fffefb;border:1px dashed #efe6de}
    .output-pre{white-space:pre-wrap;font-family:monospace;background:#fff;padding:10px;border-radius:8px;border:1px solid #f3f1ef}
    .row{display:flex;gap:8px}
    .btn{padding:10px;border-radius:8px;border:0;background:var(--accent);color:#fff;cursor:pointer}
    .hint{font-size:13px;color:var(--muted);margin-top:6px}
    footer{margin-top:30px;padding:18px;font-size:13px;color:var(--muted)}
    @media(max-width:900px){.builder{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style='font-weight:700'>{{BUSINESS_NAME}}</div>
    <nav class='nav'>
      <a href='index.html'>Home</a>
      <a href='services.html'>Sessions</a>
      <a href='blends.html' style='color:var(--accent);font-weight:600'>Custom Blends</a>
      <a href='shop.html'>Shop</a>
      <a href='contact.html'>Contact</a>
    </nav>
  </header>

  <main class='main'>
    <div class='lead'>
      <h1>Custom blend builder</h1>
      <p class='hint'>Craft a simple scent profile and get a safe, drop-based recipe with a dilution guide. This is educational and not medical advice. Always patch test and consider household pets and pregnancy when using blends.</p>
    </div>

    <section class='builder'>
      <aside class='card' aria-labelledby='build-title'>
        <h3 id='build-title'>Create a blend</h3>

        <label for='vibe'>Choose a vibe</label>
        <div class='vibes' id='vibeList'>
          <button class='vibe-btn active' data-key='calm'>Calm</button>
          <button class='vibe-btn' data-key='focus'>Focus</button>
          <button class='vibe-btn' data-key='uplift'>Uplift</button>
          <button class='vibe-btn' data-key='sleep'>Sleep</button>
          <button class='vibe-btn' data-key='ground'>Grounding</button>
        </div>

        <label for='intensity'>Intensity</label>
        <input id='intensity' type='range' min='1' max='5' value='3'>

        <label for='volume'>Bottle size (ml)</label>
        <select id='volume'>
          <option value='10'>10 ml</option>
          <option value='30'>30 ml</option>
          <option value='50'>50 ml</option>
        </select>

        <label for='audience'>User context</label>
        <select id='audience'>
          <option value='adult'>Adult (general)</option>
          <option value='pregnancy'>Pregnant / nursing — reduced strength</option>
          <option value='child'>Child under 12 — consult for safety</option>
          <option value='room'>Room-only / diffuser (not for skin)</option>
        </select>

        <div style='margin-top:12px' class='row'>
          <button class='btn' id='makeBlend'>Make blend</button>
          <button class='btn' id='resetBlend' style='background:#ddd;color:#222'>Reset</button>
        </div>

        <p class='hint'>We present total drops and an example split between 2–4 oils. For pets, choose dispersal-only or ask for pet-safe alternatives.</p>
      </aside>

      <div class='card'>
        <h3>Result & dilution guide</h3>
        <div id='resultArea'>
          <div class='blend-card'>
            <strong>Blend preview</strong>
            <div class='output-pre' id='blendPreview'>Pick options to see a recipe.</div>
            <div style='margin-top:10px;display:flex;gap:8px'>
              <button class='btn' id='copyBlend'>Copy blend card</button>
              <button class='btn' id='saveBlend' style='background:#444'>Save (local)</button>
            </div>
          </div>

          <h4 style='margin-top:14px'>Dilution guidance</h4>
          <div id='dilutionNote' class='hint'>Dilution suggestions appear here after creating a blend.</div>

          <h4 style='margin-top:14px'>Quick library</h4>
          <div style='display:flex;gap:8px;margin-top:8px'>
            <div style='padding:10px;border-radius:8px;background:#fff;border:1px solid #f0f0f0'>Calm — Lavender + Bergamot</div>
            <div style='padding:10px;border-radius:8px;background:#fff;border:1px solid #f0f0f0'>Focus — Rosemary + Lemon</div>
            <div style='padding:10px;border-radius:8px;background:#fff;border:1px solid #f0f0f0'>Uplift — Sweet Orange + Grapefruit</div>
          </div>
        </div>
      </div>
    </section>

    <section style='margin-top:20px'>
      <div class='card'>
        <h4>Notes on safety</h4>
        <p class='hint'>General adult topical dilutions often range from about 1–3%. Pregnant people, young children, and certain health contexts usually use lower dilutions (for example 0.25–1%). Diffuser or room use avoids topical dilution but still requires careful choice of oils. This tool gives general guidance — we review specifics during consultations.</p>
      </div>
    </section>

  </main>

  <footer>
    <div>{{BUSINESS_NAME}} • <a href='contact.html'>Contact</a> • <a href='book.html'>Book a consult</a></div>
    <div style='margin-top:6px;color:var(--muted)'>Questions? Email <a href='mailto:{{EMAIL}}'>{{EMAIL}}</a></div>
  </footer>

  <script>
    // Blend builder logic
    (function(){
      const vibes = {
        calm:{name:'Calm', oils:['Lavender','Bergamot','Frankincense']},
        focus:{name:'Focus', oils:['Rosemary','Lemon','Peppermint']},
        uplift:{name:'Uplift', oils:['Sweet Orange','Grapefruit','Ginger']},
        sleep:{name:'Sleep', oils:['Lavender','Cedarwood','Chamomile']},
        ground:{name:'Grounding', oils:['Vetiver','Patchouli','Cypress']}
      };

      const vibeButtons = document.querySelectorAll('.vibe-btn');
      vibeButtons.forEach(b=>b.addEventListener('click',()=>{vibeButtons.forEach(x=>x.classList.remove('active'));b.classList.add('active')}));

      function getSelectedVibe(){return document.querySelector('.vibe-btn.active').dataset.key}

      function dilutionForAudience(aud){
        // conservative guidance
        switch(aud){
          case 'adult': return 1.5; // percent
          case 'pregnancy': return 0.5;
          case 'child': return 0.5;
          case 'room': return 2.0; // diffuser % is conceptual; room use isn't topical
          default: return 1.0;
        }
      }

      function mlToDrops(ml){return Math.round(ml * 20);} // approx 20 drops per ml

      document.getElementById('makeBlend').addEventListener('click',()=>{
        const vibeKey = getSelectedVibe();
        const vibe = vibes[vibeKey];
        const intensity = parseInt(document.getElementById('intensity').value,10);
        const volume = parseInt(document.getElementById('volume').value,10);
        const audience = document.getElementById('audience').value;

        // target dilution scales with intensity (1-5): base * (intensity/3)
        const baseDil = dilutionForAudience(audience);
        const targetDil = Math.max(0.25, +(baseDil * (intensity/3)).toFixed(2));

        const totalOilMl = +(volume * (targetDil/100)).toFixed(3);
        const totalDrops = mlToDrops(totalOilMl);
        const components = vibe.oils.slice(0,3);

        // distribute drops roughly: top:50%, middle:30%, base:20% scaled to totalDrops
        const splitRatios = [0.5,0.3,0.2];
        let drops = components.map((c,i)=>Math.max(1,Math.round(totalDrops * splitRatios[i] || 0)));
        // adjust rounding to match totalDrops
        const sum = drops.reduce((a,b)=>a+b,0);
        if(sum !== totalDrops){
          const diff = totalDrops - sum;
          drops[0] = Math.max(1, drops[0] + diff);
        }

        const blendName = vibe.name + ' • ' + (targetDil) + '%';
        const lines = [];
        lines.push('Blend card: ' + blendName);
        lines.push('Bottle: ' + volume + ' ml');
        lines.push('Target dilution: ' + targetDil + ' % (approx)');
        lines.push('Total essential oil: ' + totalOilMl + ' ml (' + totalDrops + ' drops)');
        lines.push('Parts:');
        components.forEach((c,i)=>lines.push('- ' + c + ': ' + drops[i] + ' drops'));
        lines.push('\nUsage notes:');
        if(audience==='room'){
          lines.push('- Intended for diffuser/room use; do not apply to skin without dilution guidance.');
        } else {
          lines.push('- Perform a patch test before topical use. Apply a small amount on inner forearm and wait 24 hours.');
        }
        lines.push('- Keep away from eyes and sensitive areas. Avoid ingestion.');
        lines.push('- For households with pets, choose pet-safe alternates or use diffuser-only in well-ventilated spaces.');
        lines.push('\nDisclaimer: This is general guidance and not medical advice. Consult a qualified practitioner for specific health concerns.');

        document.getElementById('blendPreview').textContent = lines.join('\n');
        document.getElementById('dilutionNote').textContent = 'Suggested dilution for context: ' + targetDil + '% — adjust lower for sensitive users. Total oil ≈ ' + totalOilMl + ' ml.';
      });

      document.getElementById('copyBlend').addEventListener('click',()=>{
        const text = document.getElementById('blendPreview').textContent;
        if(!text || text.includes('Pick options')) return alert('Build a blend first');
        navigator.clipboard && navigator.clipboard.writeText(text).then(()=>{
          const b = document.getElementById('copyBlend');
          const old = b.textContent; b.textContent='Copied!'; setTimeout(()=>b.textContent=old,1200);
        }).catch(()=>alert('Copy unavailable'));
      });

      document.getElementById('resetBlend').addEventListener('click',()=>{
        document.querySelectorAll('.vibe-btn').forEach((b,i)=>b.classList.toggle('active',i===0));
        document.getElementById('intensity').value=3;document.getElementById('volume').value='10';document.getElementById('audience').value='adult';
        document.getElementById('blendPreview').textContent='Pick options to see a recipe.';
        document.getElementById('dilutionNote').textContent='Dilution suggestions appear here after creating a blend.';
      });

      // local save simple
      document.getElementById('saveBlend').addEventListener('click',()=>{
        const text = document.getElementById('blendPreview').textContent;
        if(!text || text.includes('Pick options')) return alert('Make a blend first');
