    <div style='margin-top:6px' class='small'>We ship locally in {{CITY}}, {{STATE}}. For special orders, contact us for options.</div>
  </footer>

  <script>
    // Quick preview logic
    (function(){
      const library = {
        calm:{name:'Calm', oils:['Lavender','Bergamot','Frankincense']},
        focus:{name:'Focus', oils:['Rosemary','Lemon','Peppermint']},
        uplift:{name:'Uplift', oils:['Sweet Orange','Grapefruit','Ginger']}
      };

      document.getElementById('previewBtn').addEventListener('click',()=>{
        const key = document.getElementById('quickVibe').value;
        const item = library[key];
        const volume = 10; const dilution = 1.5; // example
        const totalOilMl = +(volume * (dilution/100)).toFixed(3);
        const drops = Math.round(totalOilMl * 20) || 1;
        const ratios = [0.5,0.3,0.2];
        let parts = item.oils.map((o,i)=>Math.max(1,Math.round(drops * ratios[i])));
        const sum = parts.reduce((a,b)=>a+b,0);
        if(sum !== drops) parts[0] = Math.max(1, parts[0] + (drops - sum));

        const lines = [];
        lines.push(item.name + ' — sample for ' + volume + ' ml');
        lines.push('Dilution: ' + dilution + '% (approx)');
        lines.push('Total oil: ' + totalOilMl + ' ml (' + drops + ' drops)');
        item.oils.forEach((o,i)=>lines.push('- ' + o + ': ' + parts[i] + ' drops'));
        lines.push('\nNotes: Patch test before skin use. Avoid pet exposure to concentrated diffusions.');

        document.getElementById('quickPreview').style.display='block';
        document.getElementById('quickText').textContent = lines.join('\n');
      });

      document.getElementById('quickCopy').addEventListener('click',()=>{
        const t = document.getElementById('quickText').textContent;
        if(!t) return; navigator.clipboard && navigator.clipboard.writeText(t).then(()=>alert('Copied to clipboard'));
      });
    })();
  </script>
</body>
</html>"} 
